'use strict';
let content=[],lessons={},sources=[],subskills=[],units=[],curriculum=[];
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const info={数通:['数据通信','交换、路由与网络互联'],DCN:['数据中心 DCN','数据中心架构、云平台与算力网络'],安全:['网络安全','安全机制、防护技术与安全方案'],WLAN:['无线 WLAN','无线接入、组网、规划与运维']};
const levels={core:['基础必学','level-core'],advanced:['进阶理解','level-advanced'],detail:['技术细节','level-detail']};
const TERM_SUFFIXES=[];
function displayTerm(t){return String(t).replace(/([A-Za-z0-9+.)])([\u4e00-\u9fff])/g,'$1 $2').replace(/([\u4e00-\u9fff])([A-Za-z0-9(])/g,'$1 $2')}
function displayTitle(t){return displayTerm(t)}

let filters={group:'全部',stage:'全部',depth:'全部',query:''};
const PROGRESS_KEY='ict-progress-v1';
let progress=loadProgress();

function loadProgress(){try{const a=JSON.parse(localStorage.getItem(PROGRESS_KEY)||'[]');return new Set(Array.isArray(a)?a:[])}catch{return new Set()}}
function saveProgress(){try{localStorage.setItem(PROGRESS_KEY,JSON.stringify([...progress]))}catch{}}
function progressCount(){return [...progress].filter(id=>content.some(x=>x.id===id)).length}
function toggleProgress(id){if(progress.has(id))progress.delete(id);else progress.add(id);saveProgress();syncProgressUI();learningSidebar(id);const done=progress.has(id);document.querySelectorAll('[data-chapter]').forEach(b=>{if(b.dataset.chapter!==id)return;b.textContent=done?'✓ 已学完 · 点击取消':'标记本章已学完';b.classList.toggle('done',done);b.setAttribute('aria-pressed',String(done))})}
function syncProgressUI(){
 const total=progressCount();
 document.querySelectorAll('[data-progress-total]').forEach(n=>n.textContent=total);
 document.querySelectorAll('[data-progress-bar]').forEach(n=>n.style.width=(total/content.length*100).toFixed(1)+'%');
 document.querySelectorAll('[data-stage-progress]').forEach(n=>{const st=curriculum.find(s=>s.id===n.dataset.stageProgress);if(!st)return;const done=st.chapters.filter(c=>progress.has(c)).length;n.textContent=done+'/'+st.chapters.length;});
 document.querySelectorAll('[data-stage-bar]').forEach(n=>{const st=curriculum.find(s=>s.id===n.dataset.stageBar);if(!st)return;n.style.width=(st.chapters.filter(c=>progress.has(c)).length/st.chapters.length*100).toFixed(1)+'%'});
}
function toast(t){$('.toast').textContent=t;$('.toast').classList.add('show');setTimeout(()=>$('.toast').classList.remove('show'),2200)}
function safeURL(url){try{let u=new URL(url);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function paragraphs(t){return String(t||'').split(/\n+/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}
function badges(x){return `${x.hcia?'<span class="badge">省资格赛</span>':''}${x.hcip?'<span class="badge blue">省赛</span>':''}${!x.hcia&&!x.hcip?'<span class="badge gray">原考纲未勾选</span>':''}`}
function heading(title,sub){return `<div class="page-heading"><div><div class="eyebrow">ICT LEARNING GUIDE</div><h1>${esc(title)}</h1><p class="sub">${esc(sub)}</p></div></div>`}
function depth(t){return t==='原理/配置（原文未标级）'?'原理与配置':t}
function unitText(u){return [u.term,u.goal,u.lead,u.takeaway,u.boundary,...(u.sections||[]).flatMap(s=>[s.title,s.text,...(s.steps||[])]),u.example?[u.example.title,u.example.setup,...u.example.steps,u.example.conclusion].join(' '):'',u.check?[u.check.question,u.check.answer,u.check.why].join(' '):'',u.explain||'',u.config?.code||''].join(' ')}
function searchable(x){return [x.id,x.title,x.category,x.detail,x.explanation,x.intro,x.why,x.outcome,x.recap,x.bridge,...(x.objectives||[]),...Object.values(lessons[x.title]||{}),...subskills.filter(s=>s.parent===x.id).map(s=>s.term),...units.filter(u=>u.parent===x.id).map(unitText)].join(' ').toLowerCase()}
function mapPage(group){if(group)filters.group=Object.hasOwn(info,group)?group:'全部';return heading('考纲知识目录','按考纲阅读概念、原理、工作机制与配置，建立完整的网络知识体系。')+`<div class="track-grid">${Object.entries(info).map(([g,[t,d]])=>`<a class="track-card" href="#/map/${g}"><h2>${t}</h2><p>${d}</p><div class="meta">${content.filter(x=>x.group===g).length} 个考纲条目 →</div></a>`).join('')}</div><div class="tabs" id="group-tabs">${['全部',...Object.keys(info)].map(g=>`<button data-group="${g}" class="${filters.group===g?'active':''}">${g==='全部'?'全部方向':info[g][0]}</button>`).join('')}</div><div class="filterbar"><input id="map-query" aria-label="搜索知识点" type="search" placeholder="搜索知识点、协议或配置命令" value="${esc(filters.query)}"><select id="stage-filter" aria-label="比赛阶段"><option>全部</option><option>省资格赛</option><option>省赛</option><option>原图未勾选</option></select><select id="depth-filter" aria-label="考纲要求"><option>全部</option><option>了解</option><option>熟悉</option><option>掌握</option><option value="原理/配置（原文未标级）">原理与配置</option></select></div><div class="section-title"><h2>知识章节</h2><span class="page-count" id="result-count"></span></div><div id="knowledge-list" class="knowledge-list"></div>`}
function filtered(){return content.filter(x=>(filters.group==='全部'||x.group===filters.group)&&(filters.stage==='全部'||filters.stage==='省资格赛'&&x.hcia||filters.stage==='省赛'&&x.hcip||filters.stage==='原图未勾选'&&!x.hcia&&!x.hcip)&&(filters.depth==='全部'||x.depth===filters.depth)&&searchable(x).includes(filters.query.toLowerCase().trim()))}
function renderList(){let a=filtered();$('#result-count').textContent=`${a.length} / ${content.length} 个考纲条目`;$('#knowledge-list').innerHTML=a.length?a.map(x=>`<a class="knowledge" href="#/lesson/${x.id}"><span class="id">${x.id}</span><div><h3>${esc(displayTitle(x.title))}</h3><p>${esc(x.group)} / ${esc(x.category)} · ${esc(x.detail)}</p></div><div>${badges(x)}<span class="badge gray">${esc(depth(x.depth))}</span></div></a>`).join(''):'<p class="empty">没有匹配的知识点，请调整关键词或筛选条件。</p>'}
function flow(nodes){return `<div class="topology"><div class="flow">${nodes.map((n,i)=>`${i?'<span class="edge">→</span>':''}<div class="node">${esc(n[0])}<small>${esc(n[1])}</small></div>`).join('')}</div><p class="figcaption">原理示意 · 具体行为以协议条件和设备版本为准</p></div>`}
function stepsHTML(a){return `<ol class="process-list">${a.map((s,i)=>`<li><span>${i+1}</span><p>${esc(s)}</p></li>`).join('')}</ol>`}
function referenceHTML(a){return a.map(s=>`<div class="source"><a href="${safeURL(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.version||'')}${s.accessed?' · 查阅 '+esc(s.accessed):''}</p></div>`).join('')}
function codeHTML(code,version){return `<pre><code>${esc(code)}</code></pre>${version?`<p class="lab-note">适用参考：${esc(version)}</p>`:''}`}
function levelBadge(u){const [label,cls]=levels[u.level]||levels.core;return `<span class="level-badge ${cls}">${label}</span>`}
function unitMinutes(u){const chars=(u.lead||'').length+(u.sections||[]).reduce((n,s)=>n+s.text.length+(s.steps||[]).join('').length,0)+((u.example?.steps||[]).join('').length);return Math.max(1,Math.round(chars/380))}

function sectionHTML(s){return `<section class="unit-subsection"><h3>${esc(s.title)}</h3>${paragraphs(s.text)}${s.steps?.length?stepsHTML(s.steps):''}</section>`}
function checkHTML(c){return c?`<div class="unit-check"><p class="check-question"><strong>停下来想一想：</strong>${esc(c.question)}</p><details class="check-answer"><summary>查看参考答案</summary><p>${esc(c.answer)}</p><p class="check-why">${esc(c.why)}</p></details></div>`:''}
function exampleHTML(w){return w?`<div class="worked-example"><h3>跟着例子走：${esc(w.title)}</h3><p class="example-setup">${esc(w.setup)}</p>${stepsHTML(w.steps)}<p class="example-conclusion"><strong>由此可见：</strong>${esc(w.conclusion)}</p></div>`:''}
function advancedHTML(u){
 let out='';
 if(u.config?.code){out+=`<details class="advanced-block"><summary>配置与验证（进阶）</summary>${codeHTML(u.config.code,u.config.platform)}${u.config.notes?`<p class="lab-note">${esc(u.config.notes)}</p>`:''}${u.commandNotes?.length?`<ul class="command-notes">${u.commandNotes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}</details>`}
 else if(u.commandNotes?.length){out+=`<details class="advanced-block"><summary>命令说明（进阶）</summary><ul class="command-notes">${u.commandNotes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></details>`}
 if(u.fault?.symptom){out+=`<details class="advanced-block"><summary>常见误区与排查</summary><p><strong>${esc(u.fault.symptom)}</strong>：${esc(u.fault.cause)}。${esc(u.fault.check)}；${esc(u.fault.fix)}。</p></details>`}
 if(u.boundary){out+=`<details class="advanced-block"><summary>技术边界</summary><p>${esc(u.boundary)}</p></details>`}
 return out?`<div class="unit-advanced">${out}</div>`:''
}
const unitDiagrams={'ICT-002.05':['subnet','IPv4 地址与前缀'],'ICT-004.01':['vlan','VLAN 标签与允许列表'],'ICT-003.02':['switch','MAC 学习与转发'],'ICT-009.01':['route','最长前缀与路由选择']};
function diagramHTML(u){const d=unitDiagrams[u.id];return d?`<details class="inline-diagram" data-diagram="${d[0]}"><summary>动手演示：${esc(d[1])}</summary><div class="diagram-content"></div></details>`:''}
function unitSection(u){
 const teach=window.ICTTeaching?.forUnit(u.id)||'';
 if(!u.hasTeaching){
  return `<section class="knowledge-section level-core" id="${u.id}"><div class="unit-meta">${levelBadge(u)}<span class="section-meta">考纲要求：${esc(depth(u.depth))}</span></div><h2>${esc(displayTerm(u.term))}</h2>${paragraphs(u.explain)}${teach}${u.process?.length?`<h3>工作过程</h3>${stepsHTML(u.process)}`:''}${exampleHTML(u.walkthrough)}${advancedHTML(u)}${diagramHTML(u)}</section>`;
 }
 let visualAt=(u.sections||[]).findIndex(s=>s.steps?.length);
 if(visualAt<0)visualAt=Math.min(1,(u.sections||[]).length-1);
 let body='';
 (u.sections||[]).forEach((s,i)=>{
  body+=sectionHTML(s);
  if(teach&&i===visualAt)body+=`<div class="unit-visual">${u.visualCue?`<p class="visual-cue">${esc(u.visualCue)}</p>`:''}${teach}</div>`;
 });
 return `<section class="knowledge-section level-${u.level}" id="${u.id}"><div class="unit-meta">${levelBadge(u)}<span class="section-meta">考纲要求：${esc(depth(u.depth))}</span><span class="unit-time">约 ${unitMinutes(u)} 分钟</span></div><h2>${esc(displayTerm(u.term))}</h2><p class="unit-goal"><strong>本节要解决：</strong>${esc(u.goal)}</p><p class="unit-lead">${esc(u.lead)}</p>${body}${u.takeaway?`<p class="unit-takeaway"><strong>一句话记住：</strong>${esc(u.takeaway)}</p>`:''}${checkHTML(u.check)}${exampleHTML(u.example)}${diagramHTML(u)}${advancedHTML(u)}</section>`;
}
function orderedChapters(){return curriculum.flatMap(stage=>stage.chapters).map(id=>content.find(x=>x.id===id)).filter(Boolean)}
function learningPage(){let chapters=orderedChapters();let done=progressCount();return heading('从零开始，按顺序读懂网络','九个阶段串起全部 94 章。每章先给问题，再讲原理，最后用例子和检查确认理解。原考纲编号与范围完整保留。')+`<section class="start-guide"><h2>开始前：先认识一条通信路径</h2><p>终端是使用网络的电脑或手机。交换机连接同一个局域网里的设备；路由器连接不同的 IP 网段。网关是终端发往其他网段时交给的下一跳。无线 AP 让手机通过无线信号接入这张网络。</p><div class="plain-path">电脑 A → 交换机 → 路由器 → 另一网络的服务器</div><p>MAC 地址用于本链路的帧交付，IP 地址帮助跨网络寻找目的地，端口号把收到的数据交给对应程序。“帧”是链路层传输单元，“IP 包”是网际层传输单元；同一份上层数据会装入这些外层结构。</p><p>遇到“进阶理解”和“技术细节”标记时，可以先读完基础主线，再回头深入。每章末尾可以标记“已学完”，进度只保存在这台设备的浏览器里。</p><a class="primary" href="#/lesson/${chapters[0]?.id}">从第一章开始 →</a></section><section class="progress-panel"><div><div class="eyebrow">学习进度</div><h2><b data-progress-total>${done}</b> / ${content.length} 章已标记学完</h2><p>进度只记录你自己点击“标记本章已学完”的章节，不统计阅读时长，也不上传。</p></div><div class="progress-track"><i data-progress-bar style="width:${content.length?done/content.length*100:0}%"></i></div></section>${curriculum.map((stage,i)=>{const sd=stage.chapters.filter(c=>progress.has(c)).length;return `<section class="learning-stage" id="${stage.id}"><div class="section-title"><h2>${i+1}. ${esc(stage.title)}</h2><span class="page-count"><span data-stage-progress="${stage.id}">${sd}/${stage.chapters.length}</span> 章</span></div><p class="sub">${esc(stage.description)}</p><div class="progress-track small"><i data-stage-bar="${stage.id}" style="width:${sd/stage.chapters.length*100}%"></i></div><ol class="learning-chapters">${stage.chapters.map(id=>{let x=content.find(x=>x.id===id);const done=progress.has(id);return `<li><a href="#/lesson/${id}" class="${done?'done':''}"><strong>${done?'✓ ':''}${esc(displayTitle(x.title))}</strong><span>${esc(x.outcome)}</span></a></li>`}).join('')}</ol></section>`}).join('')}`}
function learningSidebar(id){let host=$('#learning-order');if(!host)return;let opened=new Set([...host.querySelectorAll('details[open]')].map(d=>d.dataset.stage));let active=curriculum.find(stage=>stage.chapters.includes(id));host.innerHTML=curriculum.map((stage,i)=>{const sd=stage.chapters.filter(c=>progress.has(c)).length;return `<details data-stage="${stage.id}" ${opened.has(stage.id)||active?.id===stage.id||!id&&i===0?'open':''}><summary><span>${i+1}. ${esc(stage.title)}</span><span class="stage-count" data-stage-progress="${stage.id}">${sd}/${stage.chapters.length}</span></summary><div class="progress-track mini"><i data-stage-bar="${stage.id}" style="width:${sd/stage.chapters.length*100}%"></i></div><ol>${stage.chapters.map(cid=>{let x=content.find(x=>x.id===cid);const done=progress.has(cid);return `<li><a href="#/lesson/${cid}" ${cid===id?'class="current" aria-current="page"':done?'class="done"':''}>${done?'✓ ':''}${esc(displayTitle(x.title))}</a></li>`}).join('')}</ol></details>`}).join('');if(id)host.querySelector('.current')?.scrollIntoView({block:'nearest'});else $('.sidebar').scrollTop=0;syncProgressUI()}
function getSourceIDs(x){let t=x.title;if(lessons[t]?.sources)return lessons[t].sources;if(/OSPF/.test(t))return ['ospf','routing'];if(/BGP/.test(t))return ['bgp','routing'];if(/IPv6|SRv6/.test(t))return ['ipv6'];if(/EVPN/.test(t))return ['evpn','vxlan'];if(/VXLAN/.test(t))return ['vxlan','evpn'];if(/M-LAG/.test(t))return ['mlag','vxlan','evpn'];if(/OpenStack/.test(t))return ['openstack','k8s'];if(['交换技术','网络可靠性与网络优化技术'].includes(x.category))return ['switch'];if(x.category==='路由技术')return ['routing'];if(x.title==='TCP/IP协议基础'||x.title==='以太网交换基础')return ['arp','subnet'];if(x.group==='WLAN')return /漫游/.test(t)?['roaming']:['capwap','wlansecurity'];if(x.group==='安全')return /VPN/.test(t)?['ipsec']:['security'];if(x.group==='DCN')return ['mlag','vxlan','evpn'];return ['switch','routing']}
function chapterCode(d,children){let code=d?.commands||'';let existing=new Set(children.flatMap(u=>(u.config?.code||'').split('\n')).map(s=>s.trim()));if(!existing.size||existing.size===1&&existing.has(''))return code;let extra=code.split('\n').filter(s=>s.trim()&&!existing.has(s.trim())&&!/^(system-view|quit|return)$/.test(s.trim()));return extra.every(s=>/^display /.test(s.trim()))?extra.join('\n'):code}
function lessonPage(id){
 let x=content.find(a=>a.id===id);if(!x)return heading('未找到知识点','请返回考纲目录选择章节。')+'<a class="secondary" href="#/">返回目录</a>';
 let d=lessons[x.title],children=units.filter(u=>u.parent===id),parts=subskills.filter(s=>s.parent===id),ordered=orderedChapters(),i=ordered.findIndex(c=>c.id===id),stage=curriculum.find(s=>s.chapters.includes(id));
 let refs=[...new Map([...children.flatMap(u=>u.sources||[]),...sources.filter(s=>getSourceIDs(x).includes(s.id))].map(s=>[s.url,s])).values()];
 const minutes=children.reduce((n,u)=>n+unitMinutes(u),0),done=progress.has(id);
 const outline=parts.length?`<div class="chapter-outline"><h2>本章知识点</h2><div class="outline-items">${[...parts].sort((a,b)=>{let ai=children.findIndex(u=>u.id===a.id),bi=children.findIndex(u=>u.id===b.id);return (ai<0?999:ai)-(bi<0?999:bi)}).map(s=>{const u=children.find(u=>u.id===s.id);return u?`<a href="#${s.id}" data-scroll="${s.id}" class="outline-${u.level}"><span class="outline-level">${levels[u.level][0]}</span>${esc(displayTerm(u?.term||s.term))} ↓</a>`:`<span>${esc(s.term)}</span>`}).join('')}</div></div>`:'';
 return `<a class="back" href="#/map/${x.group}">← ${esc(info[x.group][0])} / ${esc(x.category)}</a><div class="lesson-layout"><article class="lesson"><div class="mark-row"><span class="eyebrow">${x.id}</span>${badges(x)}<div class="read-tools"><button id="font-less" aria-label="缩小正文字号">A−</button><button id="font-more" aria-label="放大正文字号">A＋</button><button id="print-chapter">打印</button></div></div><p class="reading-position">${stage?esc(stage.title):''} · 第 ${i+1} / ${ordered.length} 章 · ${children.length} 个知识点 · 约 ${minutes} 分钟</p><h1>${esc(displayTitle(x.title))}</h1><button id="chapter-progress" class="progress-toggle ${done?'done':''}" data-chapter="${id}" aria-pressed="${done}">${done?'✓ 已学完 · 点击取消':'标记本章已学完'}</button><section class="chapter-intro"><h2>从一个问题开始</h2><p>${esc(x.intro)}</p>${x.why?`<p class="chapter-why"><strong>为什么现在学：</strong>${esc(x.why)}</p>`:''}${x.objectives?.length?`<div class="chapter-objectives"><h3>读完本章，你应该能</h3><ul>${x.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>`:''}<p class="chapter-outcome"><strong>能力目标：</strong>${esc(x.outcome)}</p></section><details class="syllabus-detail"><summary>查看原考纲要求</summary><div class="original"><b>考纲要求</b>${esc(x.detail)}</div></details>${outline}${x.prerequisites.length?`<p class="prerequisites">建议先阅读：${x.prerequisites.map(p=>{let a=content.find(c=>c.id===p);return a?`<a href="#/lesson/${p}">${esc(displayTitle(a.title))}</a>`:''}).join(' · ')}</p>`:''}${children.map(u=>unitSection(u)).join('')}<section id="recap" class="chapter-recap"><h2>把本章串起来</h2>${paragraphs(x.recap||x.explanation)}${x.bridge?`<div class="next-bridge"><strong>接下来</strong><p>${esc(x.bridge)}</p></div>`:''}</section>${chapterCode(d,children)?`<details class="chapter-advanced"><summary>章节配置与查询（进阶）</summary>${codeHTML(chapterCode(d,children),d.version)}</details>`:''}${d?.fault?`<details class="chapter-advanced"><summary>关键边界与易错点（进阶）</summary>${paragraphs(d.fault)}</details>`:''}${refs.length?`<details class="chapter-advanced" id="references"><summary>参考资料与协议依据</summary>${referenceHTML(refs)}</details>`:`<p class="lab-note">相关技术文档可在<a href="#/sources">参考资料</a>中查阅。</p>`}<p class="lab-note">配置以所注产品版本为参考，尚未在赛事设备上验证。交互演示中的简化条件见各演示的“模型条件与技术边界”。</p><button class="progress-toggle bottom ${done?'done':''}" data-chapter="${id}" aria-pressed="${done}">${done?'✓ 已学完 · 点击取消':'标记本章已学完'}</button><div class="chapter-pagination">${ordered[i-1]?`<a href="#/lesson/${ordered[i-1].id}">← 上一章：${esc(displayTitle(ordered[i-1].title))}</a>`:'<a href="#/learn">← 学习顺序</a>'}${ordered[i+1]?`<a href="#/lesson/${ordered[i+1].id}">下一章：${esc(displayTitle(ordered[i+1].title))} →</a>`:'<a href="#/learn">返回学习顺序 →</a>'}</div></article><aside class="toc"><p>本章目录</p>${children.map(u=>`<a href="#${u.id}" data-scroll="${u.id}" class="toc-${u.level}">${esc(displayTerm(u.term))}</a>`).join('')}<a href="#recap" data-scroll="recap">本章小结</a><a href="#references" data-scroll="references">参考资料</a></aside></div>`
}
function sourcePage(){return heading('考纲与参考资料','查阅原始考纲，以及相关产品文档与协议标准。')+`<section class="panel"><h2>考纲范围</h2><p class="sub">保留数通、DCN、安全、WLAN 四个方向的 94 条考纲条目。省资格赛与省赛按原考纲勾选标注，未勾选项仍保留。</p><div class="actions"><a class="secondary" href="assets/syllabus.png" target="_blank">查看原始考纲 ↗</a><a class="secondary" href="handbook.html">阅读离线手册 ↗</a></div></section><section class="panel method-panel"><h2>这套教程怎样讲</h2><p class="sub">每个知识点先给一个具体问题，再解释它为什么存在、怎样发生、在真实网络里怎样观察。基础必学、进阶理解和技术细节分别标注；配置、异常和技术边界收进折叠区，避免打断原理阅读。每章末尾有小结与下一章衔接，每个基础知识点有一道简短的理解检查。</p></section><div class="section-title"><h2>技术文档与标准</h2></div><section class="panel">${sources.map(s=>`<div class="source"><a href="${safeURL(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.version)} · ${esc(s.scope)}</p></div>`).join('')}</section>`}
function bind(route,id){
 if(route==='map'){for(let k of ['stage','depth']){let e=$('#'+k+'-filter');e.value=filters[k];e.onchange=()=>{filters[k]=e.value;renderList()}}$('#map-query').oninput=e=>{filters.query=e.target.value;renderList()};$('#group-tabs').onclick=e=>{let b=e.target.closest('[data-group]');if(!b)return;filters.group=b.dataset.group;$('#group-tabs').querySelectorAll('button').forEach(z=>z.classList.toggle('active',z===b));renderList()};renderList()}
 if(route==='lesson'&&$('#font-more')){$('#font-more').onclick=()=>{$('#main').classList.remove('small');$('#main').classList.add('wide')};$('#font-less').onclick=()=>{$('#main').classList.remove('wide');$('#main').classList.add('small')};$('#print-chapter').onclick=()=>{document.querySelectorAll('details[data-diagram]').forEach(d=>{d.open=true;loadDiagram(d)});window.print()};document.querySelectorAll('details[data-diagram]').forEach(d=>{d.ontoggle=()=>{if(d.open)loadDiagram(d)}});document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>toggleProgress(b.dataset.chapter))}
 document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();let target=document.getElementById(a.dataset.scroll);if(target){if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({block:'start'})}})
}
function loadDiagram(details){const host=details.querySelector('.diagram-content');if(!host||host.dataset.loaded)return;let kind=details.dataset.diagram;host.innerHTML=({subnet:subnetHTML,switch:switchHTML,vlan:vlanHTML,route:routeHTML}[kind])();host.dataset.loaded='1';bindDiagram(kind)}
function render(){let raw;try{raw=decodeURIComponent(location.hash.slice(1)||'/').split('?')[0]}catch{raw='/'}let [,r,id]=raw.split('/');if(!r)r='learn';let anchor=null;if(r==='unit'){let u=units.find(u=>u.id===id);if(u){id=u.parent;r='lesson';anchor=u.id}}let route=r==='lesson'?'lesson':r==='sources'?'sources':r==='learn'?'learn':'map';if(route==='map'&&!['map',''].includes(r||''))filters.group='全部';$('#crumb').textContent=route==='lesson'?'知识点讲解':route==='sources'?'考纲与参考资料':route==='learn'?'推荐学习顺序':'考纲知识目录';document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===(route==='lesson'?'learn':route)));$('.sidebar').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');$('#main').classList.remove('wide','small');$('#main').innerHTML=route==='lesson'?lessonPage(id):route==='sources'?sourcePage():route==='learn'?learningPage():mapPage(r==='map'?id:null);bind(route,id);if(route==='lesson'&&window.ICTTeaching){window.ICTTeaching.mount($('#main'));window.ICTTeaching.annotate($('.lesson'),{layered:true,chapter:id})}learningSidebar(route==='lesson'?id:null);syncProgressUI();window.scrollTo(0,0);if(anchor)document.getElementById(anchor)?.scrollIntoView();document.title=(route==='lesson'?(displayTitle(content.find(x=>x.id===id)?.title||'知识点讲解')):$('#crumb').textContent)+' · 网络探索站'}
function search(){let q=$('#global-search').value.trim().toLowerCase();let parents=content.filter(x=>!q||searchable(x).includes(q)).slice(0,q?20:12);let children=q?units.filter(u=>unitText(u).toLowerCase().includes(q)).slice(0,8):[];$('#search-results').innerHTML=parents.length||children.length?children.map(u=>`<a href="#/unit/${u.id}">${esc(displayTerm(u.term))}<small>${esc(displayTitle(content.find(x=>x.id===u.parent).title))} · 知识点讲解</small></a>`).join('')+parents.map(x=>`<a href="#/lesson/${x.id}">${esc(displayTitle(x.title))}<small>${esc(x.group)} / ${esc(x.category)}</small></a>`).join(''):'<p class="empty">没有匹配结果。</p>'}
$('.search-open').onclick=()=>{$('#search-dialog').showModal();$('#global-search').focus();search()};$('#global-search').oninput=search;$('#search-results').onclick=e=>{if(e.target.closest('a'))$('#search-dialog').close()};$('.nav-close').onclick=()=>{$('.sidebar').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')};$('.menu').onclick=()=>{$('.sidebar').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String($('.sidebar').classList.contains('open')))};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.sidebar').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('.search-open').click()}});window.addEventListener('hashchange',render);$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};
(window.ICT_DATA?Promise.resolve(window.ICT_DATA):Promise.all(['content.json','lessons.json','sources.json','subskills.json','units.json','curriculum.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error('无法加载 '+p);return r.json()})))).then(([c,l,s,sub,u,cur])=>{content=c;lessons=l;sources=s;subskills=sub;units=u||[];curriculum=cur||[];progress=loadProgress();render()}).catch(e=>{$('#main').innerHTML=`<p class="empty">${esc(e.message)}。请使用本地HTTP服务打开。</p>`});
